// Antes: el dato derivado se guarda y cada camino que cambia un despacho tiene que acordarse de actualizarlo.
const modelo = { cargados: 15, capacidad: 20, despachos: [{ id: 2, bultos: 4, estado: 'nuevo' }], pendientes: 4 };
const vistaLista = () => console.log('lista:', modelo.despachos.map((d) => d.estado).join(','));
const vistaContador = () => console.log('contador pendientes:', modelo.pendientes);

function asignarDesdePantalla(id) { // camino 1: se acuerda de todo
  const d = modelo.despachos.find((x) => x.id === id);
  d.estado = 'asignado'; modelo.cargados += d.bultos; modelo.pendientes -= d.bultos;
}
function asignarDesdeProcesoNocturno(id) { // camino 2: escrito seis meses después por otra persona, se olvida del contador
  const d = modelo.despachos.find((x) => x.id === id);
  d.estado = 'asignado'; modelo.cargados += d.bultos;
}
asignarDesdeProcesoNocturno(2);
vistaLista(); vistaContador();

// MVVM a mano: Model (datos y regla), ViewModel (lo que la pantalla muestra) y una View mínima que solo dibuja.
class Observable {
  constructor() { this.oyentes = []; }
  suscribir(f) { this.oyentes.push(f); }
  avisar(cual) { this.oyentes.forEach((f) => f(cual)); }
}

// Model: no sabe nada de pantallas.
const vehiculo = { patente: 'AA111AA', capacidad: 20, cargados: 15 };
const despacho = { id: 5, cliente: 'Panadería Centro', bultos: 5 };

// ViewModel: expone propiedades listas para mostrar y comandos.
class AsignarViewModel extends Observable {
  constructor(vehiculo, despacho) {
    super();
    this.vehiculo = vehiculo; this.despacho = despacho; this.asignado = false;
  }
  get textoCapacidad() { return `${this.vehiculo.cargados} de ${this.vehiculo.capacidad} bultos`; }
  get entra() { return this.vehiculo.cargados + this.despacho.bultos <= this.vehiculo.capacidad; }
  get botonHabilitado() { return this.entra && !this.asignado; }
  get mensaje() { return this.asignado ? 'Asignado' : this.entra ? 'Entra' : 'No entra'; }
  cambiarBultos(n) { this.despacho.bultos = n; this.avisar('bultos'); }   // la View escribe, el ViewModel avisa
  asignar() {
    if (!this.botonHabilitado) return;
    this.vehiculo.cargados += this.despacho.bultos; this.asignado = true; this.avisar('asignado');
  }
}

// View: se suscribe y redibuja. No decide nada.
function crearVista(vm, nombre) {
  const dibujar = () => console.log(`[${nombre}] ${vm.textoCapacidad} | ${vm.mensaje} | botón ${vm.botonHabilitado ? 'activo' : 'apagado'}`);
  vm.suscribir(dibujar); dibujar();
}

const vm = new AsignarViewModel(vehiculo, despacho);
crearVista(vm, 'pantalla');
vm.cambiarBultos(6);
vm.cambiarBultos(5);
vm.asignar();

// Se prueba el ViewModel sin ninguna pantalla:
const vm2 = new AsignarViewModel({ patente: 'BB222BB', capacidad: 20, cargados: 18 }, { id: 9, cliente: 'Kiosco Sur', bultos: 3 });
console.log('prueba sin vista ->', vm2.mensaje, vm2.botonHabilitado);

// Flujo unidireccional en 25 líneas: acción -> reductor -> estado nuevo -> vistas.
function crearStore(reductor, inicial) {
  let estado = Object.freeze(inicial); const oyentes = []; const registro = [];
  return {
    estado: () => estado,
    registro: () => registro,
    suscribir: (f) => oyentes.push(f),
    despachar(accion) {
      registro.push(accion);
      estado = Object.freeze(reductor(estado, accion));
      oyentes.forEach((f) => f(estado, accion));
    },
  };
}

const inicial = {
  capacidad: 20, cargados: 15,
  despachos: [
    { id: 1, cliente: 'Ferretería Norte', bultos: 12, estado: 'nuevo' },
    { id: 2, cliente: 'Kiosco Sur', bultos: 4, estado: 'nuevo' },
    { id: 3, cliente: 'Taller Oeste', bultos: 6, estado: 'nuevo' },
  ],
};

// Reductor: función pura. Mismo estado + misma acción = mismo resultado.
function reductor(s, a) {
  switch (a.tipo) {
    case 'asignar': {
      const d = s.despachos.find((x) => x.id === a.id);
      if (!d || d.estado !== 'nuevo' || s.cargados + d.bultos > s.capacidad) return s; // regla: no entra, nada cambia
      return { ...s, cargados: s.cargados + d.bultos, despachos: s.despachos.map((x) => (x.id === a.id ? { ...x, estado: 'asignado' } : x)) };
    }
    case 'cancelar': {
      const d = s.despachos.find((x) => x.id === a.id);
      if (!d || d.estado !== 'asignado') return s;
      return { ...s, cargados: s.cargados - d.bultos, despachos: s.despachos.map((x) => (x.id === a.id ? { ...x, estado: 'nuevo' } : x)) };
    }
    default: return s;
  }
}

// Dato derivado: se calcula, no se guarda (así no puede quedar desincronizado).
const pendientes = (s) => s.despachos.filter((d) => d.estado === 'nuevo').reduce((t, d) => t + d.bultos, 0);

const store = crearStore(reductor, inicial);
store.suscribir((s, a) => console.log(`vista: tras ${JSON.stringify(a)} -> ${s.cargados}/${s.capacidad} cargados, ${pendientes(s)} bultos pendientes`));

store.despachar({ tipo: 'asignar', id: 2 });   // 15+4 = 19, entra
store.despachar({ tipo: 'asignar', id: 3 });   // 19+6 = 25, no entra
store.despachar({ tipo: 'cancelar', id: 2 });
store.despachar({ tipo: 'asignar', id: 3 });   // 15+6 = 21, no entra
store.despachar({ tipo: 'asignar', id: 1 });   // 15+12 = 27, no entra

// Repetición: con solo el registro de acciones se reconstruye el estado.
const repetido = store.registro().reduce(reductor, inicial);
console.log('registro:', store.registro().length, 'acciones');
console.log('repetición igual al estado vivo:', JSON.stringify(repetido) === JSON.stringify(store.estado()));

// El estado es de solo lectura: una vista que intenta escribir directo no logra nada.
const escribio = Reflect.set(store.estado(), 'cargados', 0);
console.log('escritura directa aceptada:', escribio, '| cargados sigue en', store.estado().cargados);
